code='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    counts = {"up": 0, "down": 0}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    p = (y+dy, x+dx)
                    if 0 <= p[0] < h and 0 <= p[1] < w and grid[p[0]][p[1]] == 2 and p not in seen:
                        seen.add(p)
                        q.append(p)
            rows = {}
            for y, x in comp:
                rows.setdefault(y, []).append(x)
            if len(comp) == 4 and len(rows) == 2:
                counts["up" if len(next(iter(rows.values()))) == 1 and min(rows) == min(rows, key=lambda y: len(rows[y])) else "down"] += 1
    out = [[0] * 6 for _ in range(3)]
    corners = [(0,0), (0,2), (2,0), (2,2)]
    for key, color, col_offset in (("up", 3, 0), ("down", 1, 3)):
        for i in range(min(counts[key], len(corners))):
            y, x = corners[i]
            out[y][x + col_offset] = color
    return out
'''
